class TestClass {
    static int value = 100;
    static { System.out.print("Init "); }
}
// In Main:
Class<?> c = Class.forName("TestClass");
System.out.print(TestClass.value);

class PrepClass {
    static final int CONSTANT = 42;
    static { System.out.print("Init "); }
}
// In Main:
int x = PrepClass.CONSTANT;
System.out.print(x);

// loaderA and loaderB are different loaders
Class<?> classA = loaderA.loadClass("com.example.Service");
Class<?> classB = loaderB.loadClass("com.example.Service");
Object obj = classB.getDeclaredConstructor().newInstance();
com.example.Service service = (com.example.Service) obj; // Cast to loaderA's type

class Test {
    static { System.out.print("Init "); }
}
// In Main:
Class.forName("Test", false, Main.class.getClassLoader());
System.out.print("Done");

// Scenario A:
Class.forName("NonExistentClass");

// Scenario B:
// A class was compiled successfully, but at runtime the class definition cannot be found.
